public class Fixture{public void Run(Graphics g,int offset_x,int offset_y,int width,int height,int[][] colors){int left=offset_x;int top=offset_y;int across=width;int down=height;g.SetColor(Graphics.GetColorOfRGB(colors[0][0],colors[0][1],colors[0][2]));g.DrawRect(left,top,across-1,down-1);
int x=offset_x+1;int y=offset_y+1;int w=width-2;int h=height-2;g.SetColor(Graphics.GetColorOfRGB(colors[2][0],colors[2][1],colors[2][2]));g.DrawLine(x,y,x+w-1,y);g.DrawLine(x,y+1,x,y+h-2);g.SetColor(Graphics.GetColorOfRGB(colors[3][0],colors[3][1],colors[3][2]));g.DrawLine(x,y+h-1,x+w-1,y+h-1);g.DrawLine(x+w-1,y+1,x+w-1,y+h-2);
